before = await browser.query(tab_id='t_rows', selector='#rows input.quantity', fields=['ref', 'value'])
if before['truncated'] or before['data']['more'] is not False:
    raise ValueError('Read a narrower table before changing any value')
rows = before['data']['items']
if not all(row['value'].isascii() and row['value'].isdigit() for row in rows):
    raise ValueError('A value is redacted or not an unsigned integer')
for row in rows:
    await browser.input(tab_id='t_rows', target={'ref': row['ref']}, text=str(int(row['value']) + 1))
after = await browser.query(tab_id='t_rows', selector='#rows input.quantity', fields=['value'])
emit({'observed': after['data'], 'truncated': after['truncated']})
